ROOT=[dict(id='C1503',meaning='编织；交织成结构',core='线织成布，字句也能织成文章',image='text 是织成的文字；context 是一起织着的上下文；texture 是织法和结构带来的质感；pretext 是摆在前面遮掩真实意图的一层理由。',intro='拉丁 texere 是编织，分词 textus 是织成的。从纤维怎样连起来，可以过渡到字句怎样连成作品，也能过渡到材料的质地。不要把全族都强译成“文字”：textile 和 texture 仍更贴近实物结构。',forms='tex- 与 text- 是相关形式，不是两个互不相干的根。subtle 较难认：通常通过拉丁 tēla“织物、经线”及 subtīlis“精细”联系这一族，而不是今天的英语 sub- 加一个 tle。它的 b 不发音。',branches=[['把文字织起来','text、textbook、textual、textually、hypertext、subtext'],['把背景织进来','context、contextual、contextualize、contextualization'],['纤维与质感','textile、texture、textured、textural'],['精细得不明显','subtle、subtlety、subtly'],['摆在前面的理由','pretext'],['加密前后','plaintext、ciphertext：text 一项相同，差别在是否经过加密']],contrasts='textual 谈文本，textural 谈质地；只多一个 r，理解对象就变了。pretext 是借口，subtext 是潜台词，context 是上下文或背景。subtle 不等于秘密，只是常常需要留心才看得出来。',practice='用一碗汤比较 taste 与 texture，用两个版本的文章比较 textual 与 textural，再把一句可能被误解的话放回 context。解释一次以送书为由见面的行为，为什么送书可能只是 pretext。',words=list(family),sources=['https://www.etymonline.com/word/text','https://www.etymonline.com/word/subtle','https://www.etymonline.com/word/textual'])]
